custom_css:
/* 蓝调 v1.1 2025-11-25
   主题作者：咩野(DC@lambkinling)
   请勿二传二改，倒卖&商用引流司马 */

/* 编辑改色: 修改ST自带调色盘中的“UI背景”以及“UI边框”;
   自定义文字: 已在代码中使用📍标记，自行修改。
   头像: 可以分别调整user/char头像上下位置，让角色的脸露出来，在3.5头像区域自调整
*/

:root {
  --阴影: color-mix(in srgb, var(--SmartThemeBorderColor) 75%, transparent);
}

/* ===== 1. 文本样式 ===== */
/* 对话 */
q {
  text-shadow: 
    1px 1px 0 #fff,
    1.2px 1.2px 0 #ccc,
    1.3px 1.3px 0 currentColor;
}

/* 斜体 */
em {
    text-decoration: 0.1em underline dashed currentColor;
    text-underline-offset: 2.5px;
}

/* 删除 */
del {
    color: var(--SmartThemeUnderlineColor);
    text-decoration-color: crimson;
}

/* 代码块 */
body code {
    background: var(--SmartThemeUnderlineColor) !important;
    color: #fff;
    border: none;
    border-radius: 2px;
}

.mes pre code {
    background: var(--SmartThemeBlurTintColor) !important;
    border-radius: 2px;
    border: none;
}

/* md引用文本 */
blockquote {
    border-color: var(--SmartThemeUnderlineColor) !important;
    background: linear-gradient(to right, var(--SmartThemeBlurTintColor), transparent) !important;
}

/* ----- 代码块内文字(不完整) ----- */
.hljs {
  color: var(--SmartThemeBodyColor) !important;
  font-size: var(--mainFontSize) !important;
  line-height: 1.6;
}

/* md标题 */
.hljs-section {
  color: var(--SmartThemeEmColor) !important;
}

/* md粗体 */
.hljs-strong {
  color: var(--SmartThemeQuoteColor) !important;
}

/* ===== 2. 滚动条 & 滑动条 ===== */
/* ----- 2.1 滚动条 ----- */
::-webkit-scrollbar {
    width: 4px;
}

::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 75%, var(--SmartThemeBlurTintColor)) !important;
    border-radius: 1px !important;
    border: none !important;
    box-shadow: none !important;
}

/* ----- 2.2 滑动条 ----- */
input[type="range"] {
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 75%, var(--SmartThemeBlurTintColor)) !important;
    border-radius: 5px !important;
    height: 2px !important;
    filter: none !important;
    box-shadow: none !important;
}

input[type="range"]::-webkit-slider-thumb {
    filter: none !important;
    box-shadow:0 0 1.5px 0.1px var(--SmartThemeBlurTintColor);
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 70%, var(--SmartThemeBlurTintColor));
    border: none;
    border-radius: 2px;
    outline: 1px solid var(--SmartThemeBlurTintColor);
    outline-offset: -3px;
    transform: rotate(45deg) scale(0.8);
}

/* ===== 3. 聊天区域 ===== */
/* ----- 3.1 欢迎页 ----- */
.welcomePanel .recentChatList .recentChat {
    margin-bottom: 10px;
    border-radius: 5px;
    background-color: var(--SmartThemeBlurTintColor);
    outline: 1.5px solid var(--SmartThemeBlurTintColor) !important;
    box-shadow: 0 0 3px 1px var(--阴影);
}

#chat {
    border: none;
    background: transparent;
    scrollbar-width: none;
}

/* ----- 3.2 气泡框 ---- */
.mes {
    flex-direction: column;
    width: 100%; /* 宽度 */
    margin: 0 auto; /* 第一个值为上下外边距 */
    border-bottom: 1px dashed var(--SmartThemeBorderColor); /* 区分线 */
    padding: 20px 10px; /* 内边距 */
    border-radius: 0px; /* 圆角大小 */
    background: var(--SmartThemeBlurTintColor);
}

/* 消息框底部和输入框距离 */
.last_mes {
    margin-bottom: 70px !important;
}

/* --- 文字区域 --- */
.mes_block {
  padding: 0;
  overflow: visible;
}

.last_mes .mes_block {
    margin-bottom: 40px;
}

/* --- 文本框 --- */
.mes_text {
    text-align: justify;
    padding: 5px 8px; /* 内边距 */
    background: var(--SmartThemeChatTintColor);
    border-radius: 5px;
}

.mes[is_user="true"] p:last-child {
    margin-bottom: 0;
}

/* 隐藏所有空 p 标签(空段落) */
.mes_text p:empty {
    display: none;
}

/* --- 小铅笔 --- */
.mes_button,
.mes_edit_buttons {
  color: var(--SmartThemeBorderColor);
  font-size: var(--mainFontSize);
  filter: none !important;
}

/* 收藏 */
.fa-star::before {
    content: "\f004" !important; 
}

/* 收藏聊天记录 选中状态 */
#chat .fa-solid.fa-star {
    color: red !important;
}

/* 编辑 */
.mes_edit::before {
    content: "\f56b";
}

/* 消息操作菜单 */
.extraMesButtonsHint::before {
    content: "\f560" !important;
}

/* 子按钮 */
.mes .menu_button {
    opacity: 1; 
    border-radius: 5px;
}

/* --- 左右箭头 --- */
.swipe_right::before,
.swipe_left::before {
    content: "\f35a";
    opacity: 0.5;
    color: var(--SmartThemeBorderColor);
}

.swipe_left::before {
    content: "\f359";
 }

.swipeRightBlock {
  margin-right: 10px;
}

/* ----- 3.3 思维链 ----- */
.mes_reasoning_header {
    background-color: var(--SmartThemeUnderlineColor);
    padding: 3px 12px;
    margin-top: 0;
}

/* 📍思维链文字自定义 */
.mes_reasoning_header_title {
  font-size: 0;
  &::before {
    content: "⋄ 轶事记录 ⋄";
    font-size: calc(var(--mainFontSize) * 0.9);
    color: var(--SmartThemeBodyColor);
  }
}

.mes_reasoning_arrow {
  display: none;
}

/* 内容宽度 */
.mes_reasoning_details {
  width: 100%;
  position: relative;
}

/* 确保编辑按钮不被挤压 */
.mes_reasoning_actions {
  position: absolute;
  right: 5px;
  top: 5px;
  z-index: 10;
  flex-shrink: 0;
  padding: 4px 8px;
}

/* 响应式处理 */
@media (max-width: 768px) {
  .mes_reasoning {
      width: 100%;
      padding: 10px;
      max-height: 600px; 
      overflow: hidden auto;
      font-size: calc(var(--mainFontSize) * 0.9);
      border-radius: 5px;
      border: 1.5px dashed var(--SmartThemeBorderColor);
  }
  .mes_reasoning_actions {
    right: -2px;
    top: -5px;
  }
}

/* ----- 3.4 名字区域 ----- */
.mes .ch_name {
    position: relative;
    white-space: nowrap;
    margin-bottom: 4.3em; /* 📍底部为文案留空，调节此处,1em大概一行的空白 */
}

/* 📍Char - 文案自定义，\A是手动换行符 */
.mes .ch_name::after {
    content: "生活是在黑暗与光明、快乐与痛苦、信任与背叛之间跳舞，爱也是。\ALife is a dance between dark and light, pleasure and pain, trust and betrayal. Love is like that, too.";
    position: absolute;
    top: 100%;
    left: 0.3em;
    opacity:0.65;
    white-space: pre-wrap;
    font-size: calc(var(--mainFontSize) * 0.75); /* 文字大小，主题字体的0.75倍 */
}

/* User - 文案自定义 */
.mes[is_user="true"] .ch_name::after {
    content: "自然不会想让一棵橡树变成松树，不会想让一朵玫瑰变成向日葵，它只是让一切都成为它应该成为的样子。\ANature does not want an oak tree to become a pine tree, nor a rose to be a sunflower, but for everything to be what it is meant to be.";
}

/* 📍名字前后缀自定义 */
.mes .name_text {
  color: var(--SmartThemeQuoteColor);
  font-size: calc(var(--mainFontSize) * 1.2);
  &::before{
    content: "‧₊˚𝐃𝐫𝐞𝐚𝐦𝐬ഒ˚˖"; /* Char - 名字前缀 */
    color: var(--SmartThemeBodyColor);
    font-size: calc(var(--mainFontSize) * 1.5);
    }
}

/* User - 名字前缀 */
.mes[is_user="true"] .name_text::before {
    content: "‧₊˚𝐒𝐚𝐤𝐮𝐫𝐚⊹₊";
}

/* -- 名字后缀 -- */
/* Char */
.mes .name_text::after {
    content: " ✦₊⁺ ";
}

/* User */
.mes[is_user="true"] .name_text::after {
    content: " ✧₊⁺ ˚";
}

/* 📍时间戳 */
.mes .timestamp {
  position: absolute;
  top: -20px;
  right: 15px;
  opacity: 0.75;
  color: var(--SmartThemeBorderColor);
  background-color: #fff;
  background-clip: text;
  -webkit-text-stroke: 1.2px transparent;
  text-shadow: none !important;
  &::before, &::after {
    content: " - ";
  }
}

.flex-container .alignItemsBaseline {
    gap: 1px;
}

/* ----- 3.5 头像区域 -----*/
.last_mes .mesAvatarWrapper {
    padding-bottom: 0 !important;
}

.mesAvatarWrapper {
  display: flex;
  flex-direction: column;
  position: relative;
  width: 100%;
  padding: 0 3px;
}

/* by @Junezz 复古macOS风 */
body.square-avatars .avatar,
body.square-avatars .avatar img {
    border-radius: 5px !important;
}

.mes .avatar {
    width: 100%;
    pointer-events: none;
}

/* 📍头像图片调整 */
.mes .avatar img {
    width: 100%; /* 头像图片宽度 */
    aspect-ratio: 16/9; /* 比例 */
    height: auto; 
    object-fit: cover;
    object-position: center 30%; /* 调整百分比，控制Char头像显示区域，上下移动 */
    outline: 1px solid var(--SmartThemeBorderColor);
    box-shadow: 0 0 3px 0.1px var(--SmartThemeBorderColor);
}

.mes[is_user="true"] .avatar img {
    object-position: center 30%; /* 调整百分比，控制用户头像显示区域 */
}

/* 楼层 + 计时器 + tokens */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none !important;
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  position: absolute;
  opacity: 0.75;
}

/* 📍楼层文案自定义 */
.mes .mesIDDisplay {
    bottom: 20px;
    right: 8px;
    z-index: 100;
    font-size: calc(var(--mainFontSize) * 2.1);
    pointer-events: none;
    padding-right: 5px;
    color: var(--SmartThemeBorderColor);
    background-color: #fff;
    background-clip: text;
    -webkit-text-stroke: 1.5px transparent;
    text-shadow: none !important;
    &::before, &::after {
        font-size: calc(var(--mainFontSize) * 1.75);
        color: #fff;
        background-color: var(--SmartThemeBorderColor);
        background-clip: text;
        -webkit-text-stroke: 1.5px transparent;
        text-shadow: none !important;
    }
    /* 📍在此修改你想要的内容 */
    &::before { content: "⋄ 𝐄𝐱𝐜𝐞𝐫𝐩𝐭 "; }
    &::after { content: " ⋄"; }
}

/* 计时器 + 词符数 */
/* 📍丝带位置调整 */
.mes .mes_timer,
.mes .tokenCounterDisplay {
    opacity: 0.85; /* 透明度 */
    font-size: calc(var(--mainFontSize) * 0.9);
    padding: 0 15px;
    left: -4px; /* 左右 */
    background: var(--SmartThemeBorderColor);
    border-top: 0.5em solid rgba(0, 0, 0, 0.3); 
    border-right: 0.8em solid transparent;
    clip-path: 
       polygon(0 100%,  
       0 0.5em,  
       0.5em 0,
       0.5em 0.5em,
       100% 0.5em,
       calc(100% - 0.8em) calc(50% + 0.25em),
       100% 100%);
    color: #fff;
}

/* 词符数上下位置 */
.mes .tokenCounterDisplay {
    bottom: 15px;
}

/* 计时器上下位置 */
.mes .mes_timer {
    bottom: 42px;
}

/* ===== 4. 菜单抽屉 ===== */
/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
    box-shadow: none;
    border: none;
}

/* 反代警告 */
.reverse_proxy_warning {
    border-color: crimson !important;
    border-radius: 2px !important;
    background-color: transparent !important;
}

/* 可移动UI预设 */
#movingUIPresets{
  margin-bottom: 0 !important;
}

/* ----- 4.1 抽屉页 ----- */
body .drawer-content {
    border-radius: 0 0 5px 5px;
    border: none;
    border-bottom: 2px solid var(--SmartThemeBorderColor);
}

/* 全屏 by NAKARI */
.drawer-content.openDrawer {
    max-height: calc(100dvh - var(--topBarBlockSize));
}

@media (max-width: 600px) {
    #left-nav-panel,
    #right-nav-panel {
        max-height: calc(100dvh - var(--topBarBlockSize));
        padding-right: 0;
    }
}

/* ----- 4.2 标题栏 ----- */
.standoutHeader,
.inline-drawer-header,
#theme-manager-header,
#user-settings-block h4:not(#theme-manager-header h4),
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder):not(#theme-manager-header h4) {
    padding: 5px 8px;
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 25%, var(--SmartThemeBlurTintColor));
    border-radius: 2px;
    border: 1px double var(--SmartThemeBlurTintColor);
    filter: none !important;
    box-shadow:0 0 2px var(--阴影);
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    background: transparent;
    border-radius: 0;
    border: none;
    border-bottom: 2px solid var(--SmartThemeBorderColor);
    box-shadow: 0 0 2px var(--阴影);
}

/* 箭头 */
.inline-drawer-icon {
    font-size: calc(var(--mainFontSize) * 1.1);
    color: var(--SmartThemeBorderColor);
    padding-right: 3px;
  filter: none !important;
}

/* 闭合状态 */
.inline-drawer-icon::before {
    content: "✿" !important;
}

/* 展开状态 */
.inline-drawer-icon.up::before {
    content: "❀" !important;
}

/* ----- 4.3 按钮 ----- */ 
.menu_button:not(.mes_edit_buttons *) {
    border-radius: 2px;
    border: none;
    box-shadow: 0 0 2px var(--阴影);
  color: var(--SmartThemeBorderColor);
  filter: none;
}

/* 警告按钮 */
#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
#persona_delete_button,
#world_popup_delete,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
    background: crimson !important;
    color: #000;
}

/* ----- 4.4 勾选框 ----- */
input[type="checkbox"] {
    background: transparent;
    border-radius: 50%;
    outline: none;
    border: none;
    transform: scale(0.6);
    box-shadow: 0 0 2px 1px var(--阴影);
}

input[type="checkbox"]:checked {
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 50%, var(--SmartThemeBlurTintColor));
    border: 1px solid var(--SmartThemeBlurTintColor);
    filter: none;
}

input[type="checkbox"]::before {
  content: none !important;
}

.checkbox_label {
  display: flex;
  align-items: center;
  gap: 0;
}

/* ----- 4.5 下拉框 ----- */
#character_sort_order,
select.text_pole,
select {
    background-color: rgba(255, 255, 255, 0.75);
    outline: none !important;
    border-radius: 3px;
    border: none;
    box-shadow: 0 0 2px var(--阴影);
} 

#tag_import_setting {
    margin-top: 5px;
}

/* ----- 4.6输入框 ----- */
/* 搜索框 + 部分输入框 */
#settingsSearch.textarea_compact,
.text_pole:not(.objective-task):not(select) {
    border-radius: 3px;
    border: none;
    box-shadow:0 0 2px var(--阴影);
    background-color: rgba(255, 255, 255, 0.75);
}

input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]){
    border-radius: 5px;
    outline: none !important;
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 25%, var(--SmartThemeBlurTintColor));
    border: none;
    box-shadow:0 0 2px var(--阴影);
}

/* 用户设置页 - 数字输入框*/
#user-settings-block input[type="number"] {
    border-radius: 0 0 5px 5px;
    background: transparent;
}

#user-settings-block input[type="range"] {
    border-radius: 5px 5px 0 0 !important;
    height: 4px !important;
}

/* ----- 4.7 弹窗 ----- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) { 
    border-radius: 2px;
    border: none;
    box-shadow: none;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
  padding-right: 5px;
}

/* 给提示词拆分添加滚动条 */
.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
}

/* 通知提示框 */
.toast.toast-success {
  color: var(--SmartThemeBodyColor) !important;
  background-color: var(--SmartThemeBorderColor) !important;
  border-radius: 5px !important;
  box-shadow: none !important;
}

/* ----- 4.8 预设页 ----- */
/* 标题栏间距 */
#left-nav-panel .inline-drawer-header {
    margin-bottom: 8px;
}

/* 说明文字(如AI可见最大上下文等) */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

/* 滑动条名称 */
.range-block-title {
  text-align: left;
}

/* 角色名称行为 + 继续后缀*/
label[for="openai_image_inlining"] + div, 
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 3px;
}

/* --- 提示词管理器 --- */
#completion_prompt_manager {
  width: 100%; /* 宽度 */
}

/* 提示词 + 总词符数 */
#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeQuoteColor) !important;
  padding: 0;
}

/* 提示词 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

/* 顶部按钮区域 */
.completion_prompt_manager_footer {
  padding: 0 !important;
}

/* 去除阴影 */
/* 提示词 + 总词符数 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}

/* 条目编辑按钮 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
    filter: none !important;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background-color: transparent;
    border-radius: 2px;
    border: none;
    border-bottom: 2px solid var(--SmartThemeBorderColor);
    box-shadow: 0 0 2px var(--阴影);
}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 0.3;
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--SmartThemeBodyColor);
}

/* 预设区域内边距 */
#completion_prompt_manager_list{
  padding: 5px 10px;
}

/* ----- 4.9 世界书 ----- */
/* 世界书条目 */
.world_entry {
  margin-top: 8px; /* 间距 */
  background: transparent;
  border-radius: 5px;
}

/* 世界书条目卡片 */
.wi-card-entry {
  border-radius: 5px;
  border: none;
  background: transparent;
}
@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header  {
      border-radius: 5px;
      border: none;
      padding-bottom: 3px;
    }
}

/* 世界书表单控件 */
.world_entry_form_control {
  background: transparent;
}

/* 单击展开 */
.inline-drawer.wide100p .inline-drawer-content {
    background: transparent !important;
    border-radius: 5px;
    margin-top: 5px;
}

/* PC端局部阴影去除 */
/* 整个选择框 */
.select2-selection.select2-selection--multiple {
  background: color-mix(in srgb, var(--SmartThemeBorderColor) 25%, var(--SmartThemeBlurTintColor));
  border: none;
  border-radius: 2px;
}

/* 世界书选择器选项 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background: rgba(255, 255, 255, 0.5);
}

/* 清除显示选项以及移除按钮背景色 */
.select2-selection__choice__remove,
.select2-selection__choice__display {
    background: transparent !important;
    line-height: 1.6;
}

/* 同时清除搜索框和显示文本 */
.select2-search__field, 
span.select2-selection.select2-selection--single {
    background: color-mix(in srgb, var(--SmartThemeBorderColor) 25%, var(--SmartThemeBlurTintColor)) !important;
    border-radius: 2px;
    border: none;
}

.select2-search__field,
.select2-dropdown.select2-dropdown--below {
    box-shadow: none !important;
}

/* ----- 4.10 图库 ----- */
.bg_example {
    border-radius: 2px !important;
    outline: none;
    border: none;
    box-shadow:0 0 1.5px 0.2px var(--SmartThemeBorderColor);
}

/* 图片名称 */
.BGSampleTitle {
    background: transparent !important;
}

.mobile-only-menu-toggle {
    border-radius: 25% !important;
}

.mobile-only-menu-toggle,
.jg-menu {
    transform: scale(0.75) !important;
    opacity: 0.5;
    background: var(--SmartThemeBorderColor) !important;
}
/* 选中状态的样式 */
.bg_example.selected-background {
    outline: 1.5px dashed var(--SmartThemeBorderColor);
}

/* ----- 4.11 拓展页 ----- */
/* 限制正则拖拽触发区域 - 仅移动端和平板 */
@media (hover: none) and (pointer: coarse) {
  .regex-script-label {
    pointer-events: none;
  }
  .regex-script-label > *:not(.regex_script_name) {
    pointer-events: auto;
  }
   .regex-script-label .drag-handle {
     pointer-events: auto;
     padding: 6px 10px; /* 调整把手大小 */
  }
}

/* 正则名称全显示 */
.regex_script_name {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

/* 正则开启开关颜色 */
.regex-toggle-on {
  color: var(--SmartThemeUnderlineColor);
}

/* ----- 4.12 用户管理器 ----- */
.avatar-container{
    border-radius: 5px;
    border: none;
}

#user_avatar_block .avatar-container.selected {
    box-shadow: 0 0 2px 0.1px var(--SmartThemeBorderColor);
    outline: 1px solid var(--SmartThemeUnderlineColor);
    outline-offset: -3px;
}

#user_avatar_block .avatar-container.selected .ch_name {
  background: var(--SmartThemeUnderlineColor);
  color: var(--SmartThemeBlurTintColor);
}

/* ----- 4.13 角色管理器 ----- */
/* 角色卡 */
.character_select {
  margin-top: calc(var(--mainFontSize) * 0.2);
}

/* 星标角色卡 */
.character_select.is_fav {
    border-radius: 1px;
    background: linear-gradient(to right top, transparent 95%, var(--SmartThemeUnderlineColor) 90%);
    border-bottom: 5px solid var(--SmartThemeUnderlineColor);
    box-shadow: 0 0 2px 0.1px var(--SmartThemeUnderlineColor);
}

/* 收藏状态 */
#favorite_button.fav_on {
    color: red !important;
}

/* 头像 + 名字 */
.character_select.is_fav .avatar {
    outline: none;
}

.character_select.is_fav .ch_name {
    color: var(--SmartThemeUnderlineColor);
}

.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}

.tag.actionable {
  font-size: calc(var(--mainFontSize) * 1);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区热切换 */
#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.5);
}

#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + 15px);
  max-height: calc(var(--avatar-base-height)* 2);
}

.avatars_inline {
  gap: 8px;
  flex-wrap: nowrap;
  overflow: visible;
}

